// Prépare la charge par secteur : le prompt système porte les règles
// d'interprétation RI0-RI10 (§ 10.4.3), la charge utilisateur est le JSON
// EXACT des métriques du secteur — conservé tel quel pour input_payload,
// sans quoi la fidélité du commentaire serait invérifiable a posteriori.
const runId = $('Ouvrir le run').first().json.run_id;
const SYSTEME = `Tu rédiges la note hebdomadaire d'un dispositif de veille économique pour le DIRIGEANT d'une PME suisse de mécanique de précision (usinage de pièces métalliques à tolérances serrées, en sous-traitance pour les secteurs horloger, médical, automobile et aérospatial). Il te lira une minute, entre deux rendez-vous. \n\nTu reçois un objet JSON contenant : « metriques », les chiffres calculés par la base — TA SEULE SOURCE CHIFFRÉE ; « cadre_de_veille », les questions de veille du secteur avec leur mécanisme causal DÉJÀ ÉTABLI par le dispositif, que tu peux mobiliser pour relier un chiffre à ce qu'il signifie ; « sante », le score de santé du secteur s'il est calculable. \n\nApplique dans l'ordre les règles d'interprétation suivantes. RI0, prioritaire sur toutes les autres — interdiction de calcul : ne produis, ne recalcule, n'arrondis et n'extrapole aucune valeur ; reprends les chiffres tels quels ; toute métrique absente ou null est signalée dans « Points à vérifier », sans conclusion — la colonne completude énonce ce qui manque et pourquoi, et tu la REPRENDS TELLE QUELLE : aucune quantité dérivée n'est admise, même triviale (ne calcule pas un nombre de points manquants depuis « 7 sur 12 » — cite « 7 point(s) sur 12 » à l'identique). RI1 — effet de base : si la période de référence paraît atypique, déclare la variation relative peu significative et privilégie le niveau absolu. RI2 — saisonnalité : ne fonde aucune lecture sur variation_periode_pct (périodes consécutives en série brute) ; fonde-la sur glissement_annuel_pct (même période de l'année précédente), ou sur moyenne_mobile_annuelle et ecart_a_la_moyenne_pct ; si les deux sont null, dis-le et abstiens-toi de qualifier l'évolution. RI3 — effets d'anticipation : un pic suivi d'un creux d'ampleur comparable est traité comme un ensemble unique, avec recherche d'une échéance réglementaire ou fiscale en hypothèse. RI4 — matérialité : si la variation est inférieure en valeur absolue à seuil_materialite_pct, déclare-la non significative et ne lui attribue aucune explication. RI5 — fiabilité : si statut_validation n'est ni valide_source ni valide_humain, abaisse d'un niveau la confiance attribuée et motive cet abaissement. RI6 — persistance : n'emploie « tendance » ou « inversion » qu'avec au moins trois périodes cohérentes — si l'historique fourni ne permet pas d'en juger, n'emploie aucun des deux termes. RI7 — volume et structure : si les deux dimensions sont fournies, analyse-les conjointement et signale toute divergence en priorité. RI8 — décomposition : si des segments évoluent en sens opposés, ne présente pas l'agrégat comme représentatif. RI9 — interdiction de causalité : formulations proscrites : « en raison de », « causé par », « s'explique par » ; admises : « concomitant avec », « hypothèse à vérifier », « compatible avec ». RI10 — hypothèses concurrentes : présente toutes les explications compatibles avec les données, chacune accompagnée de la donnée qui permettrait de trancher. \n\nFORMAT IMPOSÉ, 200 mots maximum, en français, dans CET ORDRE — la réponse d'abord, la méthode ensuite :\n1. « Ce qu'il faut retenir » — UNE phrase. Ce que disent les chiffres du marché, pas de la base. Interdiction absolue d'y mentionner un statut de validation, un nom d'indicateur, une complétude ou un vocabulaire de base de données : le dirigeant ne sait pas ce qu'est « valide_source ».\n2. « Ce que cela change pour un sous-traitant » — deux phrases au plus. La CONSÉQUENCE pour un atelier d'usinage : charge de travail attendue, matières, débouché qui s'ouvre ou se ferme, exigence technique. Appuie-toi sur le mécanisme causal du cadre de veille quand il éclaire. Ce n'est PAS une recommandation d'action — tu décris une implication, tu ne prescris rien.\n3. « À surveiller » — une ligne : le prochain chiffre qui confirmera ou infirmera, et quand.\n4. « Fiabilité » — niveau de signal (routine, à surveiller, significatif, rupture) et de confiance (élevée, moyenne, faible), avec en une ligne ce qui la limite.\n5. « Réserves de méthode » — EN DERNIER, et seulement si nécessaire : neutralisations appliquées, données manquantes reprises telles quelles, hypothèses concurrentes. C'est la section que le dirigeant saute et que le contrôleur lit.\n\nSi les chiffres ne permettent RIEN de dire sur le marché, écris-le en une phrase à la section 1 et n'invente pas de substance. Un commentaire honnêtement vide vaut mieux qu'un commentaire qui décrit l'état de la base.`;

const sortie = [];
for (const item of $input.all()) {
  const s = item.json;
  sortie.push({ json: {
    run_id: runId,
    sector_code: s.sector_code,
    charge: s.charge,
    systeme: SYSTEME,
    utilisateur: 'Secteur « ' + s.sector_code + ' ». Objet de veille (seule source autorisée) : ' + JSON.stringify(s.charge)
  } });
}
if (sortie.length === 0) throw new Error('v_dernier_point ne renvoie aucun secteur sur les zones agrégées — vérifier la vue et le filtre de zones.');
return sortie;

// Normalise la réponse du modèle, consigne les échecs. La violation de
// RI0/RI9 se détecte à la relecture humaine — c'est sa fonction — mais un
// contrôle lexical grossier des formulations proscrites est appliqué ici
// pour signalement (jamais pour correction automatique).
const sorties = [];
const incidents = [];
const lignes = $input.all();
for (let i = 0; i < lignes.length; i++) {
  const r = lignes[i].json;
  const t = $('Préparer les charges').itemMatching(i).json;
  if (r.error) { incidents.push(t.sector_code + ' : appel en échec (' + JSON.stringify(r.error).slice(0, 200) + ')'); continue; }
  // CORRIGÉ LE 24.08.2026 — même défaut que la couche 0 la veille : sur les
  // modèles à raisonnement adaptatif, content[0] N'EST PAS le texte. Il faut
  // concaténer TOUS les blocs de type « text », sans quoi la réponse est jugée
  // vide alors qu'elle est complète — diagnostic « réponse sans texte » trompeur.
  const texte = Array.isArray(r.content)
    ? (r.content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim() || null)
    : (r.content?.[0]?.text ?? null);
  if (!texte) { incidents.push(t.sector_code + ' : réponse sans texte'); continue; }
  const proscrites = ['en raison de', 'causé par', 'causée par', "s'explique par"].filter(f => texte.toLowerCase().includes(f));
  sorties.push({ json: {
    run_id: t.run_id,
    sector_code: t.sector_code,
    input_payload: JSON.stringify(t.charge),
    // CORRIGÉ LE 24.08.2026 — l'identifiant était écrit EN DUR ici,
    // indépendamment du modèle réellement appelé : les commentaires générés
    // avec claude-opus-5 étaient archivés sous « claude-opus-4-8 ». Même
    // défaut que dans la chaîne d'extraction, corrigé la veille. On lit
    // désormais ce que l'API DÉCLARE avoir exécuté.
    model: r.model || $env.MODELE_ANTHROPIC || 'inconnu',
    text: texte,
    _signalement_ri9: proscrites.length ? 'formulations proscrites détectées : ' + proscrites.join(', ') : '',
    _incidents: incidents
  } });
}
if (sorties.length === 0) {
  // Échec bruyant, jamais d'item vide vers l'écriture : le run reste
  // visible en échec et le message porte les incidents réels — la cause,
  // pas son symptôme (constaté le 17.08 : un marqueur sans run_id partait
  // à l'INSERT et la contrainte NOT NULL répondait à la place du vrai motif).
  throw new Error('Aucun commentaire généré. Incidents : ' + (incidents.join(' | ') || 'aucun incident consigné — vérifier l’appariement des items'));
}
return sorties;

